//! The explain lens for `enaction-runner-output/1` plus
//! `enaction-mind-trace/1`: golden report, commitment override, belief
//! divergence and the deferred leak verdict.
//!
//! The golden files are compared byte for byte. There is no bless mode: a
//! changed report is regenerated by hand and reviewed.

use serde_json::{Value, json};
use std::path::{Path, PathBuf};
use std::process::Command;
use ums_profile_sdk::canonical::to_canonical_string;
use ums_profile_sdk::explain::{
    ExplainError, LEAK_VERDICT, REPORT_CONTRACT, explain, explain_documents, render_text,
};

fn fixture_path(name: &str) -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests/fixtures/explain")
        .join(name)
}

fn fixture(name: &str) -> Value {
    let text = std::fs::read_to_string(fixture_path(name)).expect("fixture");
    serde_json::from_str(&text).expect("fixture JSON")
}

fn golden(name: &str) -> String {
    std::fs::read_to_string(fixture_path(name)).expect("golden file")
}

fn report(trace: &str) -> Value {
    explain(&fixture("runner-output.json"), &fixture(trace), false).expect("report")
}

fn agent<'a>(report: &'a Value, id: &str) -> &'a Value {
    report["agents"]
        .as_array()
        .expect("agents")
        .iter()
        .find(|agent| agent["agent"] == id)
        .unwrap_or_else(|| panic!("agent {id} in report"))
}

#[test]
fn json_report_matches_golden_file() {
    let report = report("mind-trace.json");
    let canonical = to_canonical_string(&report).expect("canonical");
    assert_eq!(format!("{canonical}\n"), golden("report.golden.json"));
}

#[test]
fn text_report_matches_golden_file() {
    let report = report("mind-trace.json");
    assert_eq!(render_text(&report), golden("report.golden.txt"));
}

#[test]
fn report_is_deterministic_and_independent_of_input_member_order() {
    let first = to_canonical_string(&report("mind-trace.json")).unwrap();
    // Re-serialise the inputs with members in reverse order.
    fn reverse(value: &Value) -> Value {
        match value {
            Value::Object(members) => {
                let mut out = serde_json::Map::new();
                for (name, member) in members.iter().rev() {
                    out.insert(name.clone(), reverse(member));
                }
                Value::Object(out)
            }
            Value::Array(items) => Value::Array(items.iter().map(reverse).collect()),
            other => other.clone(),
        }
    }
    let second = explain(
        &reverse(&fixture("runner-output.json")),
        &reverse(&fixture("mind-trace.json")),
        false,
    )
    .unwrap();
    assert_eq!(first, to_canonical_string(&second).unwrap());
}

#[test]
fn selected_incumbent_not_first_in_ranking_is_commitment_override() {
    let report = report("mind-trace.json");
    let a = agent(&report, "agent-a");
    // Ticks 13 and 14: ranking [evade, engage], incumbent engage, selected
    // engage. One window of two ticks.
    assert_eq!(a["commitment_override_ticks"], 2);
    assert!(a["commitment_override_ticks"].as_u64().unwrap() >= 1);
    let overrides: Vec<&Value> = a["windows"]
        .as_array()
        .unwrap()
        .iter()
        .filter(|window| window["commitment_override"] == true)
        .collect();
    assert_eq!(overrides.len(), 1);
    assert_eq!(overrides[0]["first_tick"], 13);
    assert_eq!(overrides[0]["last_tick"], 14);
    assert_eq!(overrides[0]["selected_rank"], 2);
    assert_eq!(overrides[0]["guarantee"]["level"], "tested");
    assert!(render_text(&report).contains("commitment-override"));
}

#[test]
fn selected_incumbent_that_is_first_is_not_an_override() {
    let report = report("mind-trace.json");
    // agent-b always selects its incumbent, which is always ranked first.
    assert_eq!(agent(&report, "agent-b")["commitment_override_ticks"], 0);
}

#[test]
fn selected_not_first_but_not_the_incumbent_is_not_an_override() {
    // Tick 13 (record 5): selected engage at rank 2, but the incumbent is now
    // advance. The validator refuses this as UnexplainedSelection; the lens
    // must still not call it commitment. Tick 14 remains an override.
    let mut trace = fixture("mind-trace.json");
    trace["ticks"][5]["conation"]["incumbent"] = json!("advance");
    let report = explain(&fixture("runner-output.json"), &trace, false).unwrap();
    let a = agent(&report, "agent-a");
    assert_eq!(a["commitment_override_ticks"], 1);
    let tick_13 = a["windows"]
        .as_array()
        .unwrap()
        .iter()
        .find(|window| window["first_tick"] == 13)
        .expect("tick 13 window");
    assert_eq!(tick_13["commitment_override"], false);
}

#[test]
fn trace_without_override_counts_zero() {
    let report = report("mind-trace-no-override.json");
    for agent in report["agents"].as_array().unwrap() {
        assert_eq!(agent["commitment_override_ticks"], 0, "{}", agent["agent"]);
        for window in agent["windows"].as_array().unwrap() {
            assert_eq!(window["commitment_override"], false);
        }
    }
    assert!(render_text(&report).contains("commitment-override ticks: 0"));
}

#[test]
fn affect_changes_carry_their_resolved_causes() {
    let report = report("mind-trace.json");
    let windows = agent(&report, "agent-a")["windows"]
        .as_array()
        .unwrap()
        .clone();
    assert_eq!(windows[0]["affect"]["change"], "initial");
    // Tick 12: calm -> angry, caused by event 12 (an ActionOutcome).
    let angry = &windows[1];
    assert_eq!(angry["first_tick"], 12);
    assert_eq!(angry["affect"]["change"], "changed");
    assert_eq!(angry["affect"]["previous"], "calm");
    assert_eq!(
        angry["affect"]["caused_by"],
        json!([{"id": 12, "resolved": true, "kind": "ActionOutcome", "tick": 12}])
    );
    // Tick 13 starts a new window (the ranking changed) without a token change.
    assert_eq!(windows[2]["affect"]["change"], "unchanged");
}

#[test]
fn unresolved_cause_is_shown_not_dropped() {
    let mut trace = fixture("mind-trace.json");
    trace["ticks"][3]["affect"]["caused_by"] = json!([99]);
    let report = explain(&fixture("runner-output.json"), &trace, false).unwrap();
    let windows = agent(&report, "agent-a")["windows"]
        .as_array()
        .unwrap()
        .clone();
    assert_eq!(
        windows[1]["affect"]["caused_by"],
        json!([{"id": 99, "resolved": false}])
    );
}

#[test]
fn beliefs_are_compared_with_world_truth() {
    let report = report("mind-trace.json");
    let world = |agent_id: &str, belief_id: u64| -> Value {
        agent(&report, agent_id)["beliefs"]
            .as_array()
            .unwrap()
            .iter()
            .find(|belief| belief["belief_id"] == belief_id)
            .expect("belief")
            .clone()
    };
    let diverging = world("agent-a", 1);
    assert_eq!(diverging["world"], "diverges-from-world");
    assert_eq!(diverging["world_truth"], json!(["south"]));
    assert_eq!(diverging["proposition"]["hypothesis"], "north");
    assert_eq!(world("agent-a", 2)["world"], "agrees-with-world");
    assert_eq!(world("agent-b", 3)["world"], "agrees-with-world");
    assert_eq!(world("agent-b", 4)["world"], "no-world-truth");
    assert_eq!(world("agent-b", 5)["world"], "no-claim");
    for id in [1, 2, 3, 4, 5] {
        let holder = if id <= 2 { "agent-a" } else { "agent-b" };
        assert_eq!(world(holder, id)["guarantee"]["level"], "tested");
    }
    assert!(render_text(&report).contains("diverges-from-world"));
}

#[test]
fn nested_holder_belief_is_reported_as_designed_only() {
    let report = report("mind-trace.json");
    let nested = agent(&report, r#"["agent-a","agent-b"]"#);
    let belief = &nested["beliefs"][0];
    assert_eq!(belief["belief_id"], 6);
    assert_eq!(belief["guarantee"]["level"], "designed");
}

#[test]
fn leak_verdict_is_unverified_and_never_no_leak() {
    let report = report("mind-trace.json");
    assert_eq!(LEAK_VERDICT, "unverified (no counterfactual seam)");
    assert_eq!(report["leak_verdict"], LEAK_VERDICT);
    let text = render_text(&report);
    assert!(text.contains("leak-verdict: unverified (no counterfactual seam)"));
    assert!(!text.contains("no-leak"));
    assert!(!to_canonical_string(&report).unwrap().contains("no-leak"));
}

#[test]
fn report_names_its_contracts_and_validation_state() {
    let unvalidated = report("mind-trace.json");
    assert_eq!(unvalidated["report"], REPORT_CONTRACT);
    assert_eq!(unvalidated["inputs"]["validation"], "not-validated");
    let validated = explain(
        &fixture("runner-output.json"),
        &fixture("mind-trace.json"),
        true,
    )
    .unwrap();
    assert_eq!(validated["inputs"]["validation"], "validator-accepted");
}

#[test]
fn mind_trace_with_unknown_field_is_refused() {
    let mut trace = fixture("mind-trace.json");
    trace["ticks"][0]["score"] = json!(3);
    let error = explain(&fixture("runner-output.json"), &trace, false).unwrap_err();
    assert_eq!(error.rule(), "MalformedMindTrace", "{error}");
    assert!(error.to_string().contains("score"), "{error}");
}

#[test]
fn mind_trace_with_wrong_contract_is_refused() {
    let mut trace = fixture("mind-trace.json");
    trace["contract"] = json!("enaction-mind-trace/2");
    let error = explain(&fixture("runner-output.json"), &trace, false).unwrap_err();
    assert_eq!(error.rule(), "WrongContract", "{error}");
}

#[test]
fn mind_trace_with_float_or_large_integer_is_refused() {
    let mut trace = fixture("mind-trace.json");
    trace["ticks"][0]["affect"]["attention"] = json!(0.5);
    let error = explain(&fixture("runner-output.json"), &trace, false).unwrap_err();
    assert_eq!(error.rule(), "NonInteger", "{error}");

    let mut trace = fixture("mind-trace.json");
    trace["ticks"][0]["tick"] = json!(1u64 << 53);
    let error = explain(&fixture("runner-output.json"), &trace, false).unwrap_err();
    assert_eq!(error.rule(), "IntegerOutOfRange", "{error}");
}

#[test]
fn selected_outside_ranking_is_refused() {
    let mut trace = fixture("mind-trace.json");
    trace["ticks"][0]["conation"]["selected"] = json!("reload");
    let error: ExplainError = explain(&fixture("runner-output.json"), &trace, false).unwrap_err();
    assert_eq!(error.rule(), "SelectedNotInRanking", "{error}");
}

#[test]
fn documents_are_picked_from_a_runner_stream() {
    let documents = vec![fixture("runner-output.json"), fixture("mind-trace.json")];
    let from_stream = explain_documents(&documents, false).unwrap();
    assert_eq!(from_stream, report("mind-trace.json"));
    let error = explain_documents(&documents[..1], false).unwrap_err();
    assert_eq!(error.rule(), "MissingDocument", "{error}");
}

fn stub(name: &str) -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests/fixtures/preview")
        .join(name)
}

#[test]
fn cli_preview_explain_prints_the_designer_report() {
    let output = Command::new(env!("CARGO_BIN_EXE_ums-profile"))
        .args([
            "preview",
            "--runner",
            stub("runner-deterministic.sh").to_str().unwrap(),
            "--validator",
            stub("validator-accepts.sh").to_str().unwrap(),
            "--explain",
        ])
        .output()
        .expect("ums-profile runs");
    let stdout = String::from_utf8_lossy(&output.stdout);
    assert!(
        output.status.success(),
        "{}",
        String::from_utf8_lossy(&output.stderr)
    );
    assert!(stdout.starts_with("replay-identical: ok\n"), "{stdout}");
    assert!(
        stdout.contains(
            "inputs: enaction-runner-output/1 + enaction-mind-trace/1 (validator-accepted)"
        ),
        "{stdout}"
    );
    assert!(
        stdout.contains("leak-verdict: unverified (no counterfactual seam)"),
        "{stdout}"
    );
    assert!(
        stdout.contains("commitment-override ticks: 1 of 1"),
        "{stdout}"
    );
    assert!(stdout.contains("diverges-from-world"), "{stdout}");
    assert!(!stdout.contains("no-leak"), "{stdout}");
}
